const input = $json.body || $json || {};
const eventKind = String(input.event_kind || '');
const feedbackType = String(input.feedback_type || '');
const feedbackValue = String(input.feedback_value || '');
const reactionName = String(input.reaction_name || '');
const messageId = String(input.discord_response_message_id || '');
const authorHash = String(input.feedback_author_id_hash || '').toLowerCase();
const expected = { [String.fromCodePoint(0x1F44D)]: ['positive', 'thumbs_up'], [String.fromCodePoint(0x1F44E)]: ['negative', 'thumbs_down'] };
if (!['reaction_added', 'reaction_removed'].includes(eventKind)) throw new Error('Unsupported feedback event_kind');
if (!expected[reactionName] || expected[reactionName][0] !== feedbackType || expected[reactionName][1] !== feedbackValue) throw new Error('Reaction normalization mismatch');
if (!/^\d+$/.test(messageId)) throw new Error('discord_response_message_id must be a Discord snowflake');
if (!/^[a-f0-9]{64}$/.test(authorHash)) throw new Error('feedback_author_id_hash must be a SHA-256 hex digest');
return [{ json: {
  event_kind: eventKind,
  operation: eventKind === 'reaction_added' ? 'add' : 'remove',
  feedback_source: 'reaction',
  discord_response_message_id: messageId,
  feedback_author_id_hash: authorHash,
  feedback_type: feedbackType,
  feedback_value: feedbackValue,
  reaction_name: reactionName,
  review_candidate: eventKind === 'reaction_added' && feedbackType === 'negative',
  phoenix_collector_url: 'http://trace-emitter:8001/v1/traces',
  occurred_at: String(input.occurred_at || new Date().toISOString())
} }];

const result = $json || {};
const nowNs = String(Date.now() * 1000000);
const seed = String(result.discord_response_message_id || '').padStart(32, '0').slice(-32);
const hexToBase64 = (hex) => { let value = ''; for (let i = 0; i < hex.length; i += 2) value += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16)); return btoa(value); };
const attrs = (values) => Object.entries(values).map(([key, value]) => ({ key, value: typeof value === 'boolean' ? { boolValue: value } : { stringValue: String(value ?? '') } }));
const eventName = result.matched ? 'feedback.linked' : 'feedback.unmatched';
const payload = { resourceSpans: [{ resource: { attributes: attrs({ 'service.name': 'discord-rag-bot', 'phoenix.project.name': 'discord-rag-bot-phase-10' }) }, scopeSpans: [{ scope: { name: 'n8n.phase10.feedback', version: '1.0.0' }, spans: [{ traceId: hexToBase64(seed), spanId: hexToBase64(seed.slice(0, 16)), name: eventName, kind: 1, startTimeUnixNano: nowNs, endTimeUnixNano: nowNs, attributes: attrs({ transaction_id: result.transaction_id, discord_response_message_id: result.discord_response_message_id, feedback_type: result.feedback_type, persistence_operation: result.persistence_operation, review_candidate: result.review_candidate, matched: result.matched }), status: { code: 1 } }] }] }] };
return [{ json: { ...result, event_name: eventName, phoenix_collector_url: 'http://trace-emitter:8001/v1/traces', phoenix_trace_payload: payload } }];
